import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes lists xs having an even number of coefficients
    and the largest non-zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def evaluate_polynomial(coefficients, value):
        return sum(coef * value**i for i, coef in enumerate(coefficients))

    def derivative(coefficients, value):
        return sum(i * coef * value**(i-1) for i, coef in enumerate(coefficients) if i > 0)

    if len(xs) % 2 != 0 or all(coef == 0 for coef in xs):
        raise ValueError("List must have an even number of coefficients and at least one non-zero coefficient.")

    x = 0.0
    while True:
        fx = evaluate_polynomial(xs, x)
        dfx = derivative(xs, x)
        if abs(fx) < 1e-9:
            return round(x, 2)
        x -= fx / dfx
