def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    pq = []

    # Initialize the priority queue with all possible starting points
    for i in range(n):
        for j in range(n):
            heappush(pq, (grid[i][j], i, j))

    while pq:
        val, x, y = heappop(pq)

        # If we have taken exactly k steps, return the path
        if k == 1:
            return [val]

        # Explore all four possible directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the new position is within bounds
            if 0 <= nx < n and 0 <= ny < n:
                heappush(pq, (val * 10 + grid[nx][ny], nx, ny))

        k -= 1
