def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize a list to store the maximum sum of increasing subsequences
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Base case: The maximum sum at any position with itself is the value at that position
    for j in range(n):
        dp[j][j] = arr[j]

    # Fill the dp table
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if arr[end] > arr[start]:
                dp[start][end] = max(dp[start][end], dp[start][start] + arr[end])
                for mid in range(start + 1, end):
                    dp[start][end] = max(dp[start][end], dp[start][mid] + arr[end])

    # Check if k is within the valid range and calculate the result
    if k < n:
        return dp[i][k]
    else:
        return -1

