def sum_in_range(l, r):
    # Calculate the number of odd numbers in the range
    n = (r - l + 1) // 2

    # If the starting number is even, adjust it to make it odd
    if l % 2 == 0:
        l += 1

    # Calculate the sum of the first n odd numbers starting from l
    return int(n * (l + l + 2 * (n - 1)) / 2)
